function shopRarity(n=Math.random()){return n<.008?4:n<.05?3:n<.25?2:n<.60?1:0}
function materialShopPrice(k){return Math.max(1,Math.round(({scrap:45,bolts:55,rubber:65,tape:50,electronics:125,wire:95,oil:110,precision:260}[k])*(1+Math.min(100,s.level)*.035)*(1-roomBonus(7))))}
function newShopOffer(){if(Math.random()<.24){let m=pick(materialPool(s.level));return {i:{id:uid(),material:m.id,qty:1},premium:false,cost:materialShopPrice(m.id),sold:false}}let i=make(regularBase(),Math.max(1,s.level+pick([-2,-1,0,1,2])),shopRarity());let premium=Math.random()<(i.r>=3?.45:.12);return {i,premium,cost:shopPrice(i,premium),sold:false}}
function shopRoll(free=false){if(!free){if(s.premium<2)return;s.premium-=2}s.shop=Array.from({length:6},()=>newShopOffer());s.shopAt=Date.now();save()}
function ensureShop(){if(s.shop.length!==6||Date.now()-s.shopAt>=gmShopInterval()){shopRoll(true);return}let changed=false;for(let k=0;k<6;k++){if(!s.shop[k]?.i||s.shop[k].sold){s.shop[k]=newShopOffer();changed=true}}if(changed)save()}
