function shopCanBuy(o){return !!o?.i&&!o.sold&&!battle?.running&&s[o.premium?'premium':'gold']>=o.cost&&(isMaterial(o.i)?canAddOneMaterial(o.i.material):inventoryCanReceiveGear(o.i))}
