function shopDetail(k){let o=s.shop[k];if(!o||o.sold)return;if(isMaterial(o.i))return shopMaterialDetail(k,o);let i=o.i;$('modal').hidden=false;$('modal').innerHTML=`<div class="sheet compareSheet" role="dialog" aria-modal="true" style="--r:${qualityColor52(i)}"><div class="row"><small style="color:${qualityColor52(i)}">${qualityName52(i)} · ${slots[i.slot]}</small><button class="close" onclick="closeItem()">×</button></div>${compareMarkup(i)}<button class="affixOpen" onclick="inspectAffixes('shop',${k})">Modifikatoren · ${i.mods?i.mods.length+' Affixe':'Altbestand'} ›</button><p class="tagline">${flavor(i)}</p><button class="primary" onclick="buy(${k},'${i.id}')" ${shopCanBuy(o)?'':'disabled'}>Kaufen · ${fmt(o.cost)} ${o.premium?'◆':'$'}</button></div>`}

let dungeonMode='story',dungeonList=true,dungeonPage=0;function selectDungeon(i){if(!zones[i]||(!dungeonReady(i)&&s.d[i]<zones[i][2].length))return;dp=i;dungeonList=false;render()}function dungeonHome(){dungeonList=true;render()}function setDungeonMode(m){if(battle?.running)return;if(!kwFeatureAllowed(m)){kwGate54(kwFeatureLevel(m));return;}dungeonMode=m;dungeonList=true;render()}function towerEnemy(mode='tower'){let event=mode==='event',n=event?(s.eventTower||0):s.tower,floor=1+n,l=1+Math.floor(n*1.45),type=event?(n*17+5)%foeTypes.length:(n%4*7+15)%foeTypes.length;return {enemy:(event?(typeof arenaName==='function'?arenaName(type,0):foeTypes[type][0]):towerNames[n%4])+' · '+hubLabel('Abschnitt','Section','Участок')+' '+floor,type,l,floor,cost:0,g:Math.round((100+l*35)*(1+roomBonus(11))),x:Math.round(35+l*8),tower:true,event,variance:1.12}}function dungeonReady(i){return s.keys[i]&&s.level>=zones[i][1]&&(i===0||s.d[i-1]>=zones[i-1][2].length)}function startJourney(){if(s.travel||s.shift||battle?.running)return;if(bagFull()){note('Rucksack voll – zuerst Platz schaffen.');render();return}let o=offers[mp];if(!o||!spendEnergy(o.cost))return;let duration=effectiveDuration(o);s.travel={o:{...o,duration},start:Date.now(),end:Date.now()+duration};AudioGame.fx('travel');AudioGame.voice('questStart');note('Unterwegs: '+o.name);render()}
