const FAIRY_TITLE=['Diskothek der 100 schlechten Entscheidungen','Disco of 100 Bad Decisions','Дискотека 100 плохих решений'];
const FAIRY_FLOORS=100;
function fairyProgress(){return Math.max(0,Math.min(100,Math.floor(Number(s.fairyTower)||0)))}
function fairyLevel(f){return Math.round(50+5*(f-1)+405*((f-1)/99)**1.55)}
function fairyEnemy(){let floor=fairyProgress()+1;if(floor>FAIRY_FLOORS)return null;let l=fairyLevel(floor),type=((floor-1)*37+7)%foeTypes.length;return {fairy:true,tower:true,event:false,floor,l,type,enemy:arenaName(type,0),cost:0,g:Math.round(180+l*65),x:Math.round(90+l*22),variance:1.18+.002*floor};}
