function gearDropBaseChance(o){if(o.d!==undefined)return o.bossIndex===(zones[o.d]?.[2]?.length??0)-1?.60:.50;if(o.event)return .08;if(o.tower)return .12;return o.cost===15?.35:o.cost===10?.25:.15}
