function kwWeaponEffectsLabel(id){if(id==='shrineDouble')return hubLabel('Doppelschlag des Klempners','Plumber’s double strike','Двойной удар сантехника');if(id==='shrineStrike')return hubLabel('Dreifachspülung','Triple flush','Тройной смыв');if(id==='shrineWard')return hubLabel('Dichtung der letzten Mahnung','Seal of the final notice','Прокладка последнего предупреждения');const row=KW_WEAPON_AFFIXES.find(x=>x[0]===id);return row?hubLabel(...row[5]):id==='bleed'?hubLabel('Blutung','Bleed','Кровотечение'):id==='leech'?hubLabel('Lebensraub','Life leech','Вампиризм'):hubLabel('Schwächung','Weaken','Ослабление')}
function kwWeaponProc(stats,damage,source,target,random=Math.random){
 const events=[];let extra=0,heal=0;if(!(damage>0))return {extra,heal,events};
 for(const [id,key] of KW_WEAPON_AFFIXES){const chance=Number(stats?.[key])||0;if(chance<=0||random()>=chance)continue;
  if(id==='poison'||id==='fire'){const turns=id==='poison'?3:2,power=Math.max(1,Math.round(damage*(id==='poison'?.08:.14)));const old=target[id];target[id]={turns:Math.max(turns,old?.turns||0),power:Math.max(power,old?.power||0)};}
  else if(id==='frost'||id==='shadow')target[id]={turns:2};
  else if(id==='lightning')extra+=Math.max(1,Math.round(damage*.20));
  else if(id==='holy')heal+=Math.max(1,Math.round(damage*.15));
  else if(id==='arcane')source.arcane={turns:2};
  events.push(id);
 }return {extra,heal,events};
}
function kwWeaponDot(fx){let events=[];for(const id of ['poison','fire']){const st=fx[id];if(!st?.turns)continue;events.push([id,st.power]);if(--st.turns<=0)delete fx[id];}return events}
function kwWeaponDecay(fx){for(const id of ['frost','shadow','arcane'])if(fx[id]&&--fx[id].turns<=0)delete fx[id]}
function kwWeaponDodge(chance,fx){return (chance||0)*(fx.frost?.turns>0?.5:1)}
function kwWeaponAttack(atk,fx){return atk*(fx.frost?.turns>0?.90:1)}
function kwWeaponIncoming(damage,fx,stats){
 let n=damage;
 if(fx.shadow?.turns)n*=1.10;
 if(fx.arcane?.turns){n*=.85;delete fx.arcane}
 if(stats?.shrineWard&&!fx.shrineWardUsed){n*=.75;fx.shrineWardUsed=true}
 return Math.max(1,Math.round(n));
}
function kwShrineStrike(stats,damage,fx){
 if(!stats.shrineStrike||!damage)return 0;
 fx.shrineHits=(fx.shrineHits||0)+1;
 return fx.shrineHits%3===0?Math.max(1,Math.round(damage*.22)):0;
}
