 if(proc.extra){const key=player?'e':'h',n=Math.min(b[key],proc.extra);b[key]-=n;battleLog(b,kwWeaponEffectsLabel('lightning')+': '+num(n)+' '+hubLabel('Schaden','damage','урона'),'debuff')}
