const enemyWeaponArtIds=[0,7,18,19,20,29,30,87,100,102,104,170,184,192,212];
function randomEnemyWeapon(){return enemyWeaponArtIds[crypto.getRandomValues(new Uint32Array(1))[0]%enemyWeaponArtIds.length]}
let skippingBattle=false;
function skipBattle(){
 const current=battle,encounter=current?.o;
 if(!current?.running||skippingBattle)return;
 skippingBattle=true;
 clearInterval(timer);timer=null;
 function advance(){
  try{
   for(let i=0;i<10&&battle===current&&current.running&&current.o===encounter;i++)tick();
   if(battle===current&&current.running&&current.o===encounter){setTimeout(advance,0);return}
  }catch(error){
   skippingBattle=false;
   if(battle===current&&current.running&&current.o===encounter){
    timer=setInterval(tick,gmBattleInterval(fast?180:650));
    note(hubLabel('Überspringen fehlgeschlagen. Der Kampf läuft weiter.','Skip failed. The fight continues.','Пропуск не удался. Бой продолжается.'));
    render();
   }
   console.error('Battle skip failed',error);
   parent.kwRequestCombatView?.();
  }finally{
   if(battle!==current||!current.running||current.o!==encounter){
    skippingBattle=false;
    parent.kwRequestCombatView?.();
   }
  }
 }
 setTimeout(advance,0);
}
