function roomMaterials(i){let l=s.rooms[i],f=Math.pow(l+1,1.18),req={scrap:Math.min(90,Math.ceil(2*f)),bolts:Math.min(90,Math.ceil(f))};let extra=['tape','tape','rubber','tape','wire','rubber','tape','oil','bolts','rubber','electronics','precision','wire'][i];if(s.level>=MATERIAL_GATES[extra]&&l>=1)req[extra]=Math.min(60,(req[extra]||0)+Math.ceil(f));if(l>=5&&s.level>=8)req.electronics=Math.min(60,(req.electronics||0)+Math.ceil(f*.6));if(l>=12&&s.level>=25)req.precision=Math.min(50,(req.precision||0)+Math.ceil(f*.4));return req}
function canUpgradeRoom(i){if(!kwFeatureAllowed('Ausbau'))return false;if((i===12&&s.level<20)||(i===9&&s.level<10))return false;return Number.isInteger(i)&&i>=0&&i<rooms.length&&!s.roomJob&&!battle?.running&&s.gold>=roomCost(i)&&Object.entries(roomMaterials(i)).every(([k,n])=>materialCount(k)>=n)}
function roomDetail(i){if(!Number.isInteger(i)||i<0||i>=rooms.length)return;regen();let r=rooms[i];$('modal').hidden=false;$('modal').innerHTML=`<div class="sheet"><div class="row"><b>${hubLabel('Garagenprojekt','Garage project','Проект гаража')}</b><button onclick="closeItem()">×</button></div><div class="itemintro"><img src="${roomArt[i]}"><h3>${r[0]}</h3></div><b>${hubLabel('Ausbaustufe','Upgrade level','Уровень улучшения')} ${s.rooms[i]} → ${s.rooms[i]+1}</b><small>${r[2]}: ${bonusText(i)} → ${bonusText(i,s.rooms[i]+1)}</small><div class="upgradeMats">${Object.entries(roomMaterials(i)).map(([k,n])=>`<div class="row"><img src="${materialArt(k)}" alt=""><span>${materialName(k)}</span><b class="${materialCount(k)>=n?'gain':'loss'}">${fmt(materialCount(k))}/${fmt(n)}</b></div>`).join('')}</div><div class="row"><b>$${fmt(roomCost(i))}</b><small>${longTime(roomDuration(i))}</small></div><button class="primary" onclick="upgradeRoom(${i})" ${canUpgradeRoom(i)?'':'disabled'}>${hubLabel('Ausbau starten','Start upgrade','Начать улучшение')}</button></div>`}
function upgradeRoom(i){regen();if(!canUpgradeRoom(i))return;let cost=roomCost(i),req=roomMaterials(i);if(!consumeMaterials(req))return;let now=Date.now();s.gold-=cost;s.roomJob={i,start:now,end:now+roomDuration(i)};AudioGame.fx('build');closeItem();note('Ausbau gestartet: '+rooms[i][0]);render()}
function jobUI(){let j=s.roomJob;if(!j)return '<small>Ein Garagenauftrag · unabhängig vom Hauptquartier · läuft offline</small>';let left=Math.max(0,j.end-Date.now());return `<div class="buildStatus"><div class="row"><b>${rooms[j.i][0]}</b><span id="buildClock">${longTime(left)}</span></div><div class="bar"><i id="buildBar" style="width:${clamp(100*(Date.now()-j.start)/Math.max(1,j.end-j.start),0,100)}%"></i></div></div>`}

const pfArt='@@LOCAL:ca6eb7a359378a7c2b67.webp@@';
const pfNpcName='Onkel Pfandimir';
const pfIcons=[0,1,2,4,11,12,14,17,18,22,23,24,26,29,33,34];
const pfMaxMoves=15;
let pfCash=0,pfGems=0;
function pfState(){s.pf??={round:null,wins:0,best:null,earned:0};let f=s.pf;f.wins??=0;f.best??=null;f.earned??=0;f.losses??=0;f.played??=f.wins;f.netCash??=0;f.netGems??=0;if(f.round?.hideAt&&Date.now()>=f.round.hideAt){f.round.open=[];f.round.hideAt=0}return f}
function pfShuffle(a){for(let i=a.length-1;i>0;i--){let j=rand(i+1);[a[i],a[j]]=[a[j],a[i]]}return a}
function pfBalance(v,max){return Math.max(0,Math.min(Math.floor(Math.max(0,max)),Math.floor(Number(v)||0)))}
function pfCashMax(){return Math.min(s.gold,100+s.level*100)}function pfGemMax(){return Math.min(s.premium,2+Math.floor(s.level/5))}function pfSet(kind,v){let cash=kind==='cash',n=pfBalance(v,cash?pfCashMax():pfGemMax());if(cash)pfCash=n;else pfGems=n;for(let id of [kind+'Range',kind+'Amount']){let el=$(id);if(el)el.value=n}let btn=$('pfStartBtn');if(btn)btn.textContent=pfCash||pfGems?'Runde starten':'Gratis üben';}
function pfNew(){let f=pfState();if(battle?.running||f.round&&!f.round.done)return;let cash=pfBalance(pfCash,pfCashMax()),gems=pfBalance(pfGems,pfGemMax());s.gold-=cash;s.premium-=gems;let icons=pfShuffle([...pfIcons]).slice(0,6);f.round={cards:pfShuffle([...icons,...icons]),matched:[],open:[],hideAt:0,moves:0,done:false,prize:0,stakeCash:cash,stakeGems:gems,base:0,rules:16};note('Pfandimir mischt die Karten.');AudioGame.voice('pfStart');render()}
function pfMultiplier(m,rules=16){return rules===16?(m<=7?1.75:m<=9?1.25:m<=11?1:m<=13?.5:0):(m<=8?2:m<=10?1.5:m<=12?1:m<=14?.5:0)}
function pfFinish(r,complete){if(r.done)return;let f=pfState(),legacy=r.stakeCash===undefined;let factor=complete?pfMultiplier(r.moves,r.rules||12):0;r.done=true;r.complete=complete;r.hideAt=0;r.open=[];r.factor=factor;r.prize=legacy&&complete?Math.round(r.base*(1+Math.max(0,12-r.moves)/12)):Math.floor((r.stakeCash||0)*factor);r.gemPrize=Math.floor((r.stakeGems||0)*factor);s.gold+=r.prize;s.premium+=r.gemPrize;f.played++;f.earned+=r.prize;f.netCash+=r.prize-(r.stakeCash||0);f.netGems+=r.gemPrize-(r.stakeGems||0);if(complete){kwActivityTick();f.wins++;f.best=f.best===null?r.moves:Math.min(f.best,r.moves)}if(!complete||factor<1&&!legacy)f.losses++;note(complete?'Pfandspiel abgeschlossen.':'Pfandspiel verloren.');AudioGame.fx(complete&&factor>=1?'win':'lose');AudioGame.voice(complete&&factor>=1?'pfWin':'pfLose');save()}
function pfAbort(){let r=pfState().round;if(!r||r.done||!confirm('Runde abbrechen? Der Einsatz verfällt.'))return;pfFinish(r,false);render()}
function pfFlip(i){let f=pfState(),r=f.round;if(page!=='Pfandspiel'||battle?.running||!r||r.done||!Number.isInteger(i)||i<0||i>=12||r.matched.includes(i)||r.open.includes(i)||r.hideAt)return;r.open.push(i);if(r.open.length===2){r.moves++;let [a,b]=r.open;if(r.cards[a]===r.cards[b]){r.matched.push(a,b);r.open=[];AudioGame.fx('loot2');if(r.matched.length===12)pfFinish(r,true);else if(r.stakeCash!==undefined&&r.moves>=pfMaxMoves)pfFinish(r,false);else AudioGame.voice('pfMatch')}else{if(r.stakeCash!==undefined&&r.moves>=pfMaxMoves){pfFinish(r,false);render();return}AudioGame.voice('pfMiss');r.hideAt=Date.now()+gmTime('memory',850);let current=r;setTimeout(()=>{let f=pfState();if(f.round!==current||current.done)return;if(current.stakeCash!==undefined&&current.moves>=pfMaxMoves)pfFinish(current,false);save();if(page==='Pfandspiel'&&!battle?.running)render()},gmTime('memory',900))}}save();render()}
function pfView(){let f=pfState(),r=f.round;if(r&&!r.done&&r.stakeCash!==undefined&&r.moves>=pfMaxMoves&&!r.hideAt)pfFinish(r,false);let host=`<div class="panel pfHost"><img src="${pfArt}" alt="Onkel Pfandimir"><div><b>Onkel Pfandimir</b><p>Pfandbon-Paare · ${f.played} Runden</p><small>Rekord: ${f.best===null?'—':f.best+' Züge'} · Kein Echtgeld</small></div></div>`;if(!r||r.done){pfCash=pfBalance(pfCash,pfCashMax());pfGems=pfBalance(pfGems,pfGemMax());let controls=(kind,label,n,max)=>`<label class="pfStake"><span>${label} <small>Max. Einsatz: ${num(max)}</small></span><input id="${kind}Amount" type="number" min="0" max="${Math.floor(max)}" step="1" inputmode="numeric" value="${n}" oninput="pfSet('${kind}',this.value)"><input id="${kind}Range" aria-label="${label}" type="range" min="0" max="${Math.floor(max)}" step="1" value="${n}" oninput="pfSet('${kind}',this.value)"></label>`;let net=(n)=>`${n>0?'+':''}${fmt(n)}`,result=r?.done?`<div class="pfLast"><b>${r.complete===false?'Verloren':'Runde beendet'} · ${r.moves} Züge</b><small>Auszahlung: $${fmt(r.prize||0)} · ◆ ${fmt(r.gemPrize||0)}${r.stakeCash!==undefined?' · Netto: '+net((r.prize||0)-r.stakeCash)+' $ / '+net((r.gemPrize||0)-r.stakeGems)+' ◆':''}</small></div>`:'';return host+`<div class="panel pfSetup grow">${result}<b>Einsatz wählen</b>${controls('cash','Cash ($)',pfCash,pfCashMax())}${controls('gems','Kristalle (◆)',pfGems,pfGemMax())}<small>6 Paare · maximal 15 Züge · 0 Einsatz = Übungsrunde</small><div class="pfRates"><span>6–7 Züge <b>1,75×</b></span><span>8–9 <b>1,25×</b></span><span>10–11 <b>1×</b></span><span>12–13 <b>0,5×</b></span><span>14–15 / nicht fertig <b>0×</b></span></div><small>Auszahlung inklusive Einsatz, abgerundet. Bei 0× verfällt der Einsatz. Nur erspielte Währung. Einsatzlimit steigt mit deinem Level.</small></div><button id="pfStartBtn" class="primary" onclick="pfNew()">${pfCash||pfGems?'Runde starten':'Gratis üben'}</button>`}return host+`<div class="panel row pfInfo"><span>Paare <b>${r.matched.length/2}/6</b></span><span>Züge <b>${r.moves}${r.stakeCash===undefined?'':'/'+pfMaxMoves}</b></span><span>$${fmt(r.stakeCash||0)} · ◆ ${r.stakeGems||0}</span></div><div class="panel pfBoard">${r.cards.map((v,i)=>{let m=r.matched.includes(i),o=m||r.open.includes(i);return `<button class="pfCard ${m?'matched':o?'open':''}" aria-label="Karte ${i+1}${m?' gefunden':o?' aufgedeckt':' verdeckt'}" ${m||o||r.hideAt?'disabled':''} onclick="pfFlip(${i})">${o?`<img src="${sprites[v]}" alt="Gegenstand">${m?'<span class="pfCheck">✓</span>':''}`:'<span>?</span>'}</button>`}).join('')}</div><div class="row"><small class="pfHint">${r.hideAt?'Passt nicht!':r.open.length?'Finde das Gegenstück.':'Decke zwei Karten auf.'}</small><button onclick="pfAbort()">Aufgeben</button></div>`}


const hubArt="@@LOCAL:21736ef0bfffe633b265.webp@@";
function hubLabel(de,en,ru){return missionLabel(de,en,ru)}
function garageView(){let chars=[[npcArt[0],'Mopowitsch',hubLabel('Aufträge','Quests','Задания'),'Missionen', 'quest'],[npcArt[1],'Don Miau',hubLabel('Händler','Shop','Торговец'),'Händler','dealer'],[npcArt[2],'Babuschka',hubLabel('Tresen','Bar','Стойка'),'Kiosk','bar'],[pfArt,'Pfandimir',hubLabel('Pfandspiel','Memory','Пары'),'Pfandspiel','cards']];return `<div class="hubStage grow" style="background-image:url('${hubArt}')"><div class="hubTitle">OROKAI · KURWA SUPPLIES</div>${chars.map(n=>`<button class="hubNPC ${n[4]}" onclick="go('${n[3]}')"><img alt="${n[1]}" src="${n[0]}"><span>${n[1]}<small>${n[2]}</small></span></button>`).join('')}<button class="hubSpot toilet" onclick="go('Opferraum')">${hubLabel('WC · Opferraum','WC · Shrine','Туалет · Алтарь')}</button><button class="hubSpot exit" onclick="go('Nachtdienst')">${hubLabel('Ausgang · Nacht Schicht','Exit · Night shift','Выход · Ночная смена')}</button><button class="hubSpot loft" onclick="go('Ausbau')">${hubLabel('Ausbau','Upgrades','Улучшения')} · ${rooms.length}</button>${s.travel?`<button class="hubJourney" onclick="journeyShortcut()">${hubLabel('Reise','Journey','Поездка')} · <span class="journeyTag">${Date.now()>=s.travel.end?'Bereit':missionTime(s.travel.end-Date.now())}</span></button>`:''}</div><button onclick="go('Arena')">${hubLabel('⚔ Hinterhof-Arena','⚔ Backyard arena','⚔ Дворовая арена')}</button>`}

const SHRINE_SLOTS=5;
const SHRINE_MINUTES=[13,14,15,16,17,18,19,20,21];
const SHRINE_MANA=[12,18,25,40,55,75,90,105,125];
function shrineRarity(i){return Math.max(0,Math.min(SHRINE_MINUTES.length-1,rarity47(i)||0))}
function shrineDuration(tier){return gmTime('salvage',SHRINE_MINUTES[tier]*60000)}
function shrineState(){s.shrine??={mana:0,aura:0,last:0};s.shrine.jobs??=[];return s.shrine}
function shrineNeed(){return 100+shrineState().aura*25}
function settleShrine(){let sh=shrineState(),changed=false;for(let j of sh.jobs){if(!j.done&&Date.now()>=j.end){j.done=true;sh.mana+=j.mana;changed=true}}if(changed)save()}
function shrineRecipe(i){
 const tier=shrineRarity(i),pool=materialPool(i.l).filter(m=>m.id!=='scrap');
 const out={scrap:2+tier};
 if(pool.length)out[pick(pool).id]=1+Math.floor(tier/2);
 return out;
}
function sacrifice(id){
 if(s.level<10||battle?.running)return false;
 const sh=shrineState(),k=s.bag.findIndex(i=>i.id===id),item=s.bag[k];
 if(!item||isMaterial(item)||item.locked||sh.jobs.length>=SHRINE_SLOTS)return false;
 if(!confirm(hubLabel('Item samt eingesetzten Steinen unwiderruflich in die Toilette werfen?','Permanently throw item and socketed gems into the toilet?','Безвозвратно бросить предмет вместе с камнями в унитаз?')))return false;
 const tier=shrineRarity(item),duration=shrineDuration(tier);
 const start=Math.max(Date.now(),...sh.jobs.filter(j=>!j.done).map(j=>j.end));
 const job={id:uid(),item,start,end:start+duration,materials:shrineRecipe(item),mana:Math.floor(SHRINE_MANA[tier]*(1+roomBonus(9))),done:false};
 s.bag.splice(k,1);
 sh.jobs.push(job);kwBoardRecord('sacrifices');
 sh.last=0;
 AudioGame.fx('shrine');
 closeItem();save();render();
 return true;
}
function claimSalvage(id){if(s.level<10)return false;settleShrine();let sh=shrineState(),j=sh.jobs.find(x=>x.id===id);if(!j?.done||battle?.running)return false;for(let [k,n] of Object.entries(j.materials))j.materials[k]-=addMaterial(k,n);if(Object.values(j.materials).every(n=>!n))sh.jobs=sh.jobs.filter(x=>x!==j);save();render();return true}
function flushShrine(){if(s.level<10)return false;settleShrine();let sh=shrineState(),need=shrineNeed();if(sh.mana<need||bagFull()||battle?.running)return false;let drop=make(regularBase(),Math.max(1,s.level),Math.max(3,rarity(s.level)));sh.mana-=need;sh.aura++;rememberItem(drop);let dest=inventoryReceiveGear(drop,true);if(dest==='sell'){render();return true}AudioGame.fx('loot'+drop.r);note((dest==='store'?hubLabel('Auto-Einlagern: ','Auto-stored: ','На склад: '):hubLabel('Die heilige Spülung: ','The sacred flush: ','Священный смыв: '))+name(drop));render();return true}
function shrineView(){settleShrine();let sh=shrineState();return `<div class="panel shrinePanel"><h3>${hubLabel('WC der heiligen Spülung','Toilet of Sacred Flushing','Туалет священного смыва')}</h3><b>Aura ${sh.aura} · ${sh.mana}/${shrineNeed()} Mana</b><div class="bar"><i style="width:${Math.min(100,100*sh.mana/shrineNeed())}%"></i></div><button class="primary" onclick="flushShrine()" ${sh.mana<shrineNeed()||bagFull()?'disabled':''}>${hubLabel('Heilige Spülung · Item abholen','Sacred flush · Claim item','Священный смыв · Получить предмет')}</button></div><div class="salvageJobs">${Array.from({length:SHRINE_SLOTS},(_,k)=>{let j=sh.jobs[k];return j?`<div class="panel salvageJob"><img src="${itemArt(j.item)}"><div><b>${j.done?hubLabel('Fertig','Ready','Готово'):j.start>Date.now()?hubLabel('Warteschlange','Queued','В очереди'):hubLabel('Wird verwertet','Processing','Переработка')}</b><small id="salvageClock${k}">${j.done?hubLabel('Materialien abholen','Collect materials','Забрать материалы'):longTime(j.end-Date.now())}</small><small>${Object.entries(j.materials).filter(([k,n])=>n).map(([k,n])=>materialName(k)+' ×'+n).join(' · ')}</small></div><button onclick="claimSalvage('${j.id}')" ${j.done?'':'disabled'}>${hubLabel('Abholen','Collect','Забрать')}</button></div>`:`<div class="panel salvageJob empty"><small>${hubLabel('Freier Toilettenplatz','Free toilet slot','Свободное место в туалете')}</small></div>`}).join('')}</div><small>${hubLabel('Rucksack · Item antippen, um es in die Toilette zu werfen','Backpack · Tap an item to throw it into the toilet','Рюкзак · Нажми на предмет, чтобы бросить его в унитаз')} · ${longTime(shrineDuration(0))}–${longTime(shrineDuration(SHRINE_MINUTES.length-1))}</small><div class="shrineGrid grow">${Array.from({length:BAG_CAP},(_,k)=>{let i=bagAt(k);return i&&!isMaterial(i)?slot(i,sh.jobs.length<SHRINE_SLOTS?`sacrifice('${i.id}')`:''):slot(null,'')}).join('')}</div>`}
function updateShrineClock(){let sh=shrineState(),before=sh.jobs.filter(j=>j.done).length;settleShrine();if(page!=='Opferraum')return;if(before!==sh.jobs.filter(j=>j.done).length){render();return}sh.jobs.forEach((j,k)=>{let c=$('salvageClock'+k);if(c&&!j.done)c.textContent=longTime(j.end-Date.now())})}

function roomsView(){let pages=Math.ceil(rooms.length/4);roomPage=clamp(roomPage,0,pages-1);return `<div class="panel buildInfo">${jobUI()}</div><div class="roomgrid grow">${rooms.slice(roomPage*4,roomPage*4+4).map((r,k)=>{let i=roomPage*4+k;return `<div class="panel roomcard"><img src="${roomArt[i]}" alt=""><div><b>${r[0]} · St. ${s.rooms[i]}</b><small>${r[2]}: ${bonusText(i)} → ${bonusText(i,s.rooms[i]+1)}</small><small>${s.roomJob?.i===i?'Im Ausbau':longTime(roomDuration(i))+' · $'+num(roomCost(i))}</small><button onclick="roomDetail(${i})">${s.roomJob?.i===i?'Bau läuft':hubLabel('Material & Ausbau','Materials & upgrade','Материалы и улучшение')}</button></div></div>`}).join('')}</div><div class="row"><button ${roomPage===0?'disabled':''} onclick="roomPage--;render()">‹</button><small>Projekte ${roomPage+1}/${pages}</small><button ${roomPage===pages-1?'disabled':''} onclick="roomPage++;render()">›</button></div>`}
function codexView(){let c=codexCount(),isItem=codexTab==='items',entries=isItem?catalog.map((a,i)=>({name:a[0],type:i,key:a[0],group:slots[a[1]]})):foeCatalog,known=e=>!!s.codex[isItem?'items':'foes'][e.key],list=codexFilter?entries.filter(e=>known(e)):entries,per=12,pages=Math.max(1,Math.ceil(list.length/per));codexPage=clamp(codexPage,0,pages-1);return `<div class="panel codexTop"><div class="row"><b>Chronik der fragwürdigen Taten</b><strong class="gold">${(c.ratio*100).toFixed(1)} %</strong></div><div class="bar"><i style="width:${100*c.ratio}%"></i></div><div class="row"><small>${c.found}/${c.total} entdeckt</small><b class="gold">+${(c.ratio*100).toFixed(1)} % XP</b></div></div><div class="row mode"><button class="${isItem?'active':''}" onclick="setCodex('items')">Items ${c.items}/${catalog.length}</button><button class="${!isItem?'active':''}" onclick="setCodex('foes')">Gegner ${c.foes}/${foeCatalog.length}</button></div><div class="row"><small>${isItem?'Jeder Grundgegenstand zählt einmal.':'Abenteuer, Bosse und Turmtypen.'}</small><button onclick="codexFilter=!codexFilter;codexPage=0;render()">${codexFilter?'Alle zeigen':'Nur entdeckt'}</button></div><div class="codexGrid grow">${list.slice(codexPage*per,(codexPage+1)*per).map(e=>`<button class="codexEntry ${known(e)?'':'unknown'}" onclick="codexDetail('${isItem?'items':'foes'}',${entries.indexOf(e)})"><img alt="" src="${isItem?itemArt({a:e.type}):codexPortrait(e)}"><span>${known(e)?e.name:'???'}</span></button>`).join('')}${!list.length?'<small>Noch keine Einträge entdeckt.</small>':''}</div><div class="row"><button onclick="codexPage--;render()" ${codexPage===0?'disabled':''}>‹</button><small>Seite ${codexPage+1}/${pages}</small><button onclick="codexPage++;render()" ${codexPage===pages-1?'disabled':''}>›</button></div>`}
function setCodex(t){codexTab=t;codexPage=0;render()}
function codexDetail(t,i){let item=t==='items',e=item?{key:catalog[i][0],name:catalog[i][0],type:i,group:slots[catalog[i][1]]}:foeCatalog[i];if(!e)return;let k=!!s.codex[t][e.key];$('modal').hidden=false;$('modal').innerHTML=`<div class="sheet"><div class="row"><b>${k?e.name:'Unentdeckter Eintrag'}</b><button class="close" onclick="closeItem()">×</button></div><img class="codexBig ${k?'':'unknownImg'}" src="${item?itemArt({a:e.type}):codexPortrait(e)}"><small>${e.group} · ${k?'Entdeckt':'Noch nicht '+(item?'gefunden':'besiegt')}</small>${k&&item?`<p class="tagline">${flavor({a:i})}</p>`:''}${item&&isUniqueBase(i)&&i>=UNIQUE_BASE+6?`<small class="gold">${uniqueWindowText(i-UNIQUE_BASE)}</small>`:''}<button onclick="closeItem()">Schließen</button></div>`}
function kioskCost(){return Math.max(1,Math.ceil((40+s.level*10)*(1-roomBonus(10))))}function snack(){regen();let cost=kioskCost();if(s.energy>=100||s.gold<cost)return;let gain=Math.min(20,100-s.energy);s.gold-=cost;s.energy+=gain;if(s.energy===100)s.last=Date.now();AudioGame.fx('refill');AudioGame.voice('kioskSnack');note('Babuschka: Noch '+gain+' Ausdauer für den Weg!');render()}
function kioskView(){return `<div class="panel scene kiosk"><img src="${npcArt[2]}" alt="Babuschka"><h3>Babuschkas Kiosk</h3><p>„Du kämpfst nicht auf leeren Magen!“</p><small>Kein Cooldown. Kein Gemecker. Na gut, ein bisschen Gemecker.</small></div><div class="panel stack"><div class="row"><b>Ausdauer</b><span id="kenergy">${s.energy}/100</span></div><div class="bar"><i id="kbar" style="width:${s.energy}%"></i></div><button class="primary" onclick="snack()" ${s.energy===100||s.gold<kioskCost()?'disabled':''}>Pfandbrot XXL · +20 Ausdauer · ${kioskCost()} $</button><button class="primary" onclick="refill()" ${s.energy===100||s.premium<3?'disabled':''}>Kurwa-Energy · Voll auffüllen · 3 ◆</button><small>Natürlich: +1 Ausdauer alle ${(regenStep()/1000).toFixed(1)} Sekunden.</small></div>`}
const badgeDefs=[['Hinterhof-Diplom','Erreiche Stufe 5',()=>s.level>=5,15],['Pfandbaron','Erreiche Stufe 20',()=>s.level>=20,13],['Klobürsten-Examen','10 Grunditems entdecken',()=>codexCount().items>=10,0],['Inventararchäologe','50 Grunditems entdecken',()=>codexCount().items>=50,15],['Hausordnung besiegt','25 Siege',()=>s.wins>=25,23],['Garagenabitur','Ersten Dungeon abschließen',()=>s.d[0]>=zones[0][2].length,18],['Lift kaputt','10 Turmetagen abschließen',()=>s.tower>=10,33],['Gewerbe angemeldet','5 Garagenstufen ausbauen',()=>s.rooms.reduce((a,b)=>a+b,0)>=5,16],['Nachts auf Strunz','Ersten Nachtdienst abschließen',()=>s.shifts>=1,28],['Schichtlegende','10 Nachtdienste abschließen',()=>s.shifts>=10,32],['Akademie der Ahnungslosen','Kodex zu 50 % füllen',()=>codexCount().ratio>=.5,15],['Bürokratischer Endboss','Alle Storybosse besiegen',()=>s.d.every((n,i)=>n>=zones[i][2].length),5],['Pfandbon-Genie','Erstes Pfandspiel abschließen',()=> (s.pf?.wins||0)>=1,34],['Gedächtnis aus Stahl','Alle sechs Paare in höchstens acht Zügen finden',()=>s.pf?.best!=null&&s.pf.best<=8,15],['Pfandmillionär in Ausbildung','10 Pfandspiele abschließen',()=> (s.pf?.wins||0)>=10,13]];
function checkBadges(){for(let [n,d,ok] of badgeDefs)if(ok()&&!s.badges[n]){s.badges[n]=true;AudioGame.fx('badge')}}function badgeCount(){return badgeDefs.filter(b=>s.badges[b[0]]).length}function badgeView(){return `<div class="panel codexTop"><b>Ruhmeswand der fragwürdigen Leistungen</b><small>${badgeCount()}/${badgeDefs.length} freigeschaltet · rein kosmetisch</small><div class="bar"><i style="width:${100*badgeCount()/badgeDefs.length}%"></i></div></div><div class="codexGrid grow">${badgeDefs.map(b=>`<button class="codexEntry ${s.badges[b[0]]?'':'unknown'}" onclick="badgeDetail(${badgeDefs.indexOf(b)})"><img src="${sprites[b[3]]}"><span>${b[0]}</span></button>`).join('')}</div>`}function badgeDetail(i){let b=badgeDefs[i];$('modal').hidden=false;$('modal').innerHTML=`<div class="sheet"><div class="row"><b>${b[0]}</b><button onclick="closeItem()">×</button></div><img class="codexBig ${s.badges[b[0]]?'':'unknownImg'}" src="${sprites[b[3]]}"><p>${b[1]}</p><small>${s.badges[b[0]]?'Freigeschaltet':'Noch gesperrt'}</small></div>`}
function shiftHourly(){return (65+s.level*12+3*Math.pow(Math.max(0,s.level-20),1.4))*(1+roomBonus(8))}function shiftPay(h){return Math.floor(clamp(Math.round(Number(h)||1),1,24)*shiftHourly())}function setShiftHours(v){shiftHours=clamp(Math.round(Number(v)||1),1,24);let label=$('shiftDuration'),pay=$('shiftPreview');if(label)label.textContent=shiftHours+' h';if(pay)pay.textContent='$'+fmt(shiftPay(shiftHours));let slider=$('shiftSlider');if(slider)slider.value=shiftHours;}function beginShift(){if(s.shift||s.travel||battle?.running)return;shiftHours=clamp(Math.round(Number(shiftHours)||1),1,24);let now=Date.now();s.shift={start:now,end:now+gmTime('shift',shiftHours*3600000),pay:shiftPay(shiftHours),hours:shiftHours};note(hubLabel('Nacht Schicht angetreten.','Night shift started.','Ночная смена началась.'));render()}function claimShift(){if(!s.shift||Date.now()<s.shift.end)return;let pay=s.shift.pay;s.shift=null;s.gold+=pay;kwActivityTick();s.shifts++;s.earnedShift+=pay;AudioGame.fx('cash');AudioGame.voice('shift');note('Feierabend! $'+fmt(pay)+' Cash erhalten.');render()}function cancelShift(){if(!s.shift)return;if(confirm(hubLabel('Nacht Schicht abbrechen? Kein Lohn für diese Schicht.','Cancel night shift? No pay for this shift.','Отменить ночную смену? Оплаты за смену не будет.'))){s.shift=null;note('Schicht abgebrochen.');render()}}
function shiftView(){let j=s.shift,left=j?Math.max(0,j.end-Date.now()):0;return `<div class="panel scene nightScene"><img src="${enemyArt(6)}"><h3>${hubLabel('Nacht Schicht – Auf Strunz','Night shift – Auf Strunz','Ночная смена – Auf Strunz')}</h3><small>„Kontrolliere die Garagen. Der letzte Pfandbon darf nicht entkommen.“</small>${j?`<p class="gold">Schichtlohn: $${fmt(j.pay)}</p><div class="travelClock" id="shiftClock">${left?longTime(left):'Feierabend!'}</div><div class="bar travelBar"><i id="shiftBar" style="width:${clamp(100*(Date.now()-j.start)/Math.max(1,j.end-j.start),0,100)}%"></i></div>`:'<p>Verdiene Cash auch wenn du offline bist.</p><small>Während der Schicht sind Abenteuer gesperrt. Dungeons bleiben möglich.</small>'}</div>${j?`<button class="primary" id="claimShift" onclick="claimShift()" ${left?'disabled':''}>${left?'Schicht läuft …':'Lohn abholen'}</button><button onclick="cancelShift()">Schicht abbrechen</button>`:`<div class="panel shiftPicker"><div class="row"><b>${hubLabel('Arbeitszeit','Shift duration','Длительность смены')}</b><b class="gold" id="shiftDuration">${shiftHours} h</b></div><input id="shiftSlider" type="range" min="1" max="24" step="1" value="${shiftHours}" aria-label="${hubLabel('Arbeitszeit in Stunden','Shift hours','Часы смены')}" oninput="setShiftHours(this.value)"><div class="row"><small>1 h</small><small>24 h</small></div><div class="row shiftPresets">${[1,4,8,12,24].map(h=>`<button onclick="setShiftHours(${h})">${h} h</button>`).join('')}</div><div class="row"><small>${hubLabel('Schichtlohn','Shift pay','Оплата смены')}</small><strong class="gold" id="shiftPreview">$${fmt(shiftPay(shiftHours))}</strong></div></div><button class="primary" onclick="beginShift()" ${s.travel?'disabled':''}>${s.travel?'Abenteuer läuft':hubLabel('Nacht Schicht antreten','Start night shift','Начать ночную смену')}</button>`}`}
function rankView(){return `<div class="panel scene"><h3>Rangliste</h3><p>Dein Profil: Stufe ${s.level} · ${s.wins} Siege · Turm ${s.tower}</p><small>Online-Rangliste folgt erst mit Serveranbindung. Kein fiktiver Rang.</small></div>`}

